import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DOODWC8v.js";var i=JSON.parse(`{"title":"Bento Node compatibility dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"apps/node-compat/README.md","filePath":"apps/node-compat/README.md"}`),a={name:`apps/node-compat/README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="bento-node-compatibility-dashboard" tabindex="-1">Bento Node compatibility dashboard <a class="header-anchor" href="#bento-node-compatibility-dashboard" aria-label="Permalink to “Bento Node compatibility dashboard”">​</a></h1><p>A local, read-only dashboard for two different kinds of evidence: <strong>behavioral results</strong> from upstream Node test files, and <strong>availability</strong> of globals and built-in module exports. A present export is not proof that it behaves correctly.</p><p>The app follows the Remix guest-book fixture&#39;s architecture—Remix controllers, server-rendered components, asset serving, and SQLite through <code>remix/data-table</code>—using pinned <strong>Remix 3.3.0</strong>. Node hosts the dashboard and collection tools so a Bento regression cannot prevent you from inspecting its results. Mise owns toolchains and tasks; the app never uses Bento&#39;s task runner.</p><h2 id="start-locally" tabindex="-1">Start locally <a class="header-anchor" href="#start-locally" aria-label="Permalink to “Start locally”">​</a></h2><p>From the repository root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:setup</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:4318" target="_blank" rel="noreferrer">http://127.0.0.1:4318</a>. The server binds only to loopback. <code>PORT</code> changes the port. The first visit shows an empty state with collection commands; no example results are presented as measurements.</p><h2 id="collect-evidence" tabindex="-1">Collect evidence <a class="header-anchor" href="#collect-evidence" aria-label="Permalink to “Collect evidence”">​</a></h2><p>Use a Bento executable you want to measure. Build this checkout with <code>mise run build</code>, or pass the path to another build. From the repository root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:prepare</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:collect</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ../../target/debug/bento</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --filter</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> buffer</span></span></code></pre></div><p>The executable path is relative to <code>apps/node-compat</code>. <code>--filter buffer</code> selects behavioral test paths containing <code>buffer</code>; the availability inventory still covers the full public baseline. Omit <code>--filter</code> to run the complete declared behavioral corpus. A full run can take a long time and executes trusted upstream test code with your user&#39;s authority. It is not a sandbox. Do not point the collector at untrusted executables or modified test sources.</p><p>Select one evidence kind when needed:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:collect</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --kind</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> behavior</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ../../target/debug/bento</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --filter</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> assert</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> compat:collect</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --kind</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> inventory</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ../../target/debug/bento</span></span></code></pre></div><p><code>--timeout-ms</code> sets the per-process deadline. <code>--bento-arg=ARG</code> adds an explicit Bento run argument, recorded with the evidence. Builds implementing proposal 0003 need no permission arguments for an unrestricted run. The collector does not guess a permission model or translate flags.</p><p>Collection does not run through the browser. Refresh the dashboard after a run to see its results. Ordinary test failures are measurements, not collection failures; a missing executable, invalid selection, or failed corpus preparation is an error.</p><h2 id="read-the-results" tabindex="-1">Read the results <a class="header-anchor" href="#read-the-results" aria-label="Permalink to “Read the results”">​</a></h2><p><strong>Behavior</strong> compares the same unmodified upstream files under Node and Bento. The corpus is Node <strong>26.12.1</strong>, commit <code>bc2e01dcf6acd5cf7d169b5f26cf89abaaeb41f1</code>, specifically <code>test/parallel</code> and <code>test/sequential</code> JavaScript test files and their upstream helpers and fixtures. Native-addon build suites, Web Platform Tests, and other Node test directories are outside this corpus. The dashboard shows both the corpus size and the selected size; a filtered run is not a measurement of the entire suite.</p><p>Bento requires a project manifest. The harness adds <code>{&quot;private&quot;:true}</code> as <code>test/parallel/package.json</code> and <code>test/sequential/package.json</code> in both scratch copies, under Node and Bento alike. It records this adaptation in the corpus scope. Upstream test files and helpers remain unchanged, and the cached upstream source is never patched.</p><p>Both runtimes run with <code>NODE_TEST_KNOWN_GLOBALS=0</code>, following Deno&#39;s harness: additional runtime globals are measured by the availability inventory instead of failing every behavioral file. This disables the shared harness&#39;s global-leak check, including its ability to catch globals leaked by individual tests. API assertions and <code>mustCall</code> checks remain active. The setting is recorded in the corpus scope, so runs from a different harness profile cannot be compared as regressions.</p><p>A behavioral pass requires both a passing Node control and a passing Bento execution. Failures of the Node control remain visible and are not credited as Bento compatibility. Skipped tests, unsupported flags, timeouts, crashes, and unrun cases stay distinct. No expected-failure configuration converts failures into passes. Node-style scripts can legitimately complete without TAP output; successful file execution is not a count of individual assertions. Recognized TAP skips and empty test plans are not passes.</p><p>Bento does not implement every Node command-line flag. Tests requiring unsupported flags are marked <strong>unsupported</strong>, not silently run without their requirements. Each case shows the original flags, exact invocation, exit code or signal, duration, stdout, and stderr. Logs are bounded and explicitly marked when truncated.</p><p><strong>Availability</strong> compares globals and public built-in module exports against Node, including prefix-only built-ins. Internal underscore-prefixed modules are excluded. It reports present, missing, type mismatch, or inspection error; it does not call every API or infer behavioral support. When Bento&#39;s <code>node:module.isBuiltin()</code> reports a built-in absent, every Node export from that module is missing. Other import failures are inspection errors. One failed module import does not erase the remaining inventory.</p><p><strong>History</strong> preserves runs in SQLite. A regression is a previously passing case that no longer passes under comparable conditions. Comparisons require complete behavior runs with the same corpus revision, selection, platform, Node control, launch arguments, and execution deadline. Changing the Bento build is allowed; changing the measurement conditions is not silently treated as a regression. Interrupted or failed collection remains incomplete rather than becoming a smaller, inflated pass rate.</p><h2 id="local-data-and-checks" tabindex="-1">Local data and checks <a class="header-anchor" href="#local-data-and-checks" aria-label="Permalink to “Local data and checks”">​</a></h2><p>The app stores results in <code>apps/node-compat/.data/results.sqlite</code> and caches upstream source beneath <code>.data</code>. These files are ignored by git. Collection uses a scratch copy rather than running mutable tests inside the cached source. Keep <code>.data</code> to retain history. The UI has no delete, upload, or arbitrary-command endpoint.</p><p>From <code>apps/node-compat</code>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> setup</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> prepare</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> collect</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> /absolute/path/to/bento</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --filter</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> buffer</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> dev</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> check</span></span></code></pre></div><p>The root <code>mise run check</code> also checks this app. Tests use the fixture&#39;s <code>remix/test</code>; formatting, linting, and types use Oxfmt, Oxlint, and TypeScript. No Rust crate changes are required.</p><h2 id="methodology-references" tabindex="-1">Methodology references <a class="header-anchor" href="#methodology-references" aria-label="Permalink to “Methodology references”">​</a></h2><ul><li><a href="https://github.com/nodejs/node/tree/v26.12.1/test" target="_blank" rel="noreferrer">Node&#39;s upstream tests</a> supply the behavioral corpus.</li><li><a href="https://github.com/denoland/deno/tree/main/tests/node_compat" target="_blank" rel="noreferrer">Deno&#39;s Node compatibility harness</a> and <a href="https://github.com/denoland/node_test_viewer" target="_blank" rel="noreferrer">daily viewer</a> informed the separation of full measurements, exclusions, and history.</li><li><a href="https://github.com/oven-sh/bun/tree/main/test/js/node" target="_blank" rel="noreferrer">Bun&#39;s Node tests</a> demonstrate upstream-test reuse; this dashboard stores executed results rather than inferring success from included files.</li><li><a href="https://github.com/pi0/platform-node-compat" target="_blank" rel="noreferrer">Pooya Parsa&#39;s platform-node-compat</a> informed the separate availability view. Its application code is not copied.</li></ul><p>MIT. See the repository&#39;s <code>LICENSE</code> file.</p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};